-- Production state applied in Supabase on 2026-09-23.
-- Personalized Seminar 11 project module with institutional-email access.

alter table public.seminar_student_projects
  add column if not exists project_mode text not null default 'guided_definition'
    check (project_mode in ('fixed','guided_definition')),
  add column if not exists definition_questions jsonb not null default '[]'::jsonb
    check (jsonb_typeof(definition_questions)='array');

create table if not exists public.seminar_project_access_events (
  id bigint generated by default as identity primary key,
  occurred_at timestamptz not null default clock_timestamp(),
  student_registry_id uuid references public.student_registry(id) on delete set null,
  success boolean not null,
  email_hash text,
  ip_hash text,
  user_agent text
);

create index if not exists seminar_project_access_events_student_idx
  on public.seminar_project_access_events(student_registry_id,occurred_at desc);
create index if not exists seminar_project_access_events_time_idx
  on public.seminar_project_access_events(occurred_at desc);

alter table public.seminar_project_access_events enable row level security;
revoke all on table public.seminar_project_access_events from public,anon,authenticated;
grant select,insert on table public.seminar_project_access_events to service_role;

insert into public.seminar_student_projects(
  student_registry_id,group_code,student_name,project_slug,track_slug,project_title,project_summary,objective,
  stack,source_kind,source_ref,safety_scope,sprints,assignment_status,teacher_note,decision_status,decision_note,
  confirmed_at,project_mode,definition_questions
) values
('b29dad41-bb4b-430e-8b5c-b5a3a33aeecd'::uuid,'11A','ARANGO GIRALDO JUAN PABLO','arango-web-resilience-defense-lab','cybersecurity','Web Resilience Defense Lab — DoS Mitigation in a Local Sandbox','Proyecto defensivo de ciberseguridad: construir una aplicación web local, medir su comportamiento bajo tráfico controlado y aplicar defensas como rate limiting, backoff y registro de eventos.','Demostrar, dentro de un laboratorio autorizado y únicamente local, cómo una aplicación web puede detectar, limitar y documentar ráfagas de solicitudes sin atacar servicios externos.',array['Python','FastAPI or Flask','JavaScript','rate limiting','logging','basic monitoring']::text[],'teacher','Definido por el docente: ciberseguridad defensiva / resiliencia web','Solo localhost o sandbox expresamente autorizado. No se realizan ataques a servicios externos, evasión de protección, botnets ni técnicas de indisponibilidad contra terceros.','[{"n":1,"goal":"Define the local web service, authorized scope, threat scenario and measurable success criteria.","title":"Scope + protected asset","deliverable":"README scope + asset/threat table"},{"n":2,"goal":"Model Client, TrafficSimulator, RateLimiter, AuditLog and Dashboard responsibilities.","title":"Architecture + UML","deliverable":"UML + request-flow diagram"},{"n":3,"goal":"Build the local endpoint and measure normal request rate, latency and status codes.","title":"Baseline service","deliverable":"Local app + baseline evidence"},{"n":4,"goal":"Generate bounded traffic only against localhost with configurable rate and duration.","title":"Controlled traffic simulator","deliverable":"Safe simulator + run configuration"},{"n":5,"goal":"Add rate limiting, cooldown/backoff rules and security logging.","title":"Defensive controls","deliverable":"Defense layer + blocked-request evidence"},{"n":6,"goal":"Visualize requests/sec, latency, allowed/blocked counts and event timeline.","title":"Monitoring dashboard","deliverable":"Dashboard + screenshots"},{"n":7,"goal":"Test normal, burst and invalid-input scenarios and document limits.","title":"Defensive QA","deliverable":"Test matrix + fixes"},{"n":8,"goal":"Demonstrate the lab live and explain risks, mitigations and residual limitations.","title":"Security defense","deliverable":"Final demo + security report + UML"}]'::jsonb,'assigned',null,'proposed','Proyecto específico ya delimitado. Hoy se define el alcance técnico exacto del laboratorio, métricas y entregables.',null,'fixed','["¿Qué aplicación local vas a proteger?","¿Qué métricas mostrarán que la defensa funciona?","¿Qué límites de solicitudes y duración usarás en las pruebas controladas?","¿Qué eventos deben quedar registrados en el log?"]'::jsonb),
('8f4ca26d-7e59-43aa-9f16-3ed80fec7fbe'::uuid,'11A','GOMEZ CANO SAMUEL','gomez-gta-v-mod-showcase','web','GTA V Mod Showcase — Web Catalog & Compatibility Guide','Sitio web temático de GTA V para organizar mods por categoría, versión, requisitos y compatibilidad, con búsqueda, filtros y páginas de detalle.','Construir una aplicación web completa y publicable que use datos estructurados para catalogar mods y explicar compatibilidad de forma clara.',array['HTML','CSS','JavaScript','JSON','localStorage','GitHub Pages or static hosting']::text[],'teacher','Definido por el docente a partir de la selección de desarrollo web con temática GTA V','El proyecto es informativo y de catálogo. No incluye bypass de anti-cheat, evasión de DRM, cheats, ejecución maliciosa ni instrucciones para evadir controles.','[{"n":1,"goal":"Define the target user, MVP, content rules and the mod categories to include.","title":"Scope + audience","deliverable":"README scope + backlog"},{"n":2,"goal":"Define Mod, Category, Dependency and CompatibilityRule plus navigation structure.","title":"Data model + information architecture","deliverable":"UML/data schema + wireframe"},{"n":3,"goal":"Build responsive mod cards and a detail view driven by JSON data.","title":"Catalog interface","deliverable":"Navigable catalog UI"},{"n":4,"goal":"Implement text search and filters by category, version and compatibility.","title":"Search + filters","deliverable":"Working search/filter flow"},{"n":5,"goal":"Explain requirements and dependencies for a chosen game version.","title":"Compatibility guide","deliverable":"Compatibility component + examples"},{"n":6,"goal":"Persist favorites and preferences with localStorage.","title":"Favorites + persistence","deliverable":"Saved state + reset option"},{"n":7,"goal":"Test missing data, unknown versions, mobile layout and keyboard navigation.","title":"QA + accessibility","deliverable":"QA checklist + fixes"},{"n":8,"goal":"Publish the site and defend the data model and UI decisions.","title":"Deploy + defense","deliverable":"Public deployment + final UML + live demo"}]'::jsonb,'assigned',null,'proposed','Proyecto específico definido. Hoy se concreta el alcance del catálogo, estructura de datos y funciones del MVP.',null,'fixed','["¿Qué categorías de mods incluirá el MVP?","¿Qué campos tendrá cada mod: versión, requisitos, dependencias, compatibilidad?","¿Qué filtros y búsquedas son indispensables?","¿Qué información será propia y qué enlaces externos usarás como referencia?"]'::jsonb),
('9f601a8d-108f-488f-a139-8463900067ea'::uuid,'11A','MAZO LOPEZ JERONIMO','mazo-data-analyst-definition','data-science','Python / Data Analyst Project — Define Your Question & Dataset','Ruta personalizada de análisis de datos en Python. El tema concreto no está impuesto: hoy debes escoger una pregunta real, un dataset y el producto final que vas a construir. La IA puede quedar como extensión si tiene sentido después del análisis exploratorio.','Convertir una pregunta elegida por el estudiante en un análisis reproducible: cargar datos, limpiar, explorar, visualizar, interpretar y comunicar hallazgos con Python.',array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[],'github_issue','Interés previo: Inteligencia Artificial Introductoria (Issue #13). Ruta actual abierta a Data Analyst / Python hasta definir el proyecto específico.',null,'[{"n":1,"goal":"Choose a real analytical question, dataset source, variables and success criteria.","title":"Question + dataset definition","deliverable":"Project charter + dataset link/source"},{"n":2,"goal":"Load the dataset reproducibly and understand columns, units, types and scope.","title":"Import + data dictionary","deliverable":"Notebook + data dictionary"},{"n":3,"goal":"Handle types, missing values, duplicates and obvious inconsistencies with documented decisions.","title":"Data cleaning","deliverable":"Clean dataset pipeline + before/after evidence"},{"n":4,"goal":"Compute relevant descriptive statistics and explore distributions/relationships.","title":"Descriptive analysis","deliverable":"EDA notebook section + findings"},{"n":5,"goal":"Build clear plots that directly answer parts of the analytical question.","title":"Visualization","deliverable":"At least 3 justified visualizations"},{"n":6,"goal":"Add grouping, correlation, hypothesis-style comparisons or a simple ML model only if justified.","title":"Deeper analysis / optional model","deliverable":"Analysis extension + interpretation"},{"n":7,"goal":"Organize the notebook/report, rerun from a clean state and verify every result.","title":"Data story + reproducibility QA","deliverable":"Reproducible final notebook/dashboard draft"},{"n":8,"goal":"Present the question, evidence, findings, limitations and one live code/data operation.","title":"Analyst defense","deliverable":"Final notebook/dashboard + short presentation"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy. La ruta base es Data Analyst / Python; el tema, dataset y producto final los define cada estudiante.',null,'guided_definition','["¿Qué pregunta real quieres responder con datos?","¿Qué dataset usarás y cuál es su fuente?","¿Qué variable o resultado te interesa explicar?","¿Qué 3 visualizaciones serían útiles?","¿Tu producto final será notebook, dashboard, informe o una combinación?","¿La IA/ML aporta valor real o basta con análisis estadístico y visual?"]'::jsonb),
('815536bc-c0e4-48b7-b59f-fec01943c041'::uuid,'11A','RODRIGUEZ PEÑA JERONIMO','rodriguez-robotics-definition','robotics','Robotics Project — Define the Robot Mission','Ruta personalizada de robótica. Hoy se define qué problema resolverá el robot o sistema automatizado, qué sensores/actuadores necesita y si el primer prototipo será simulado o físico.','Diseñar e implementar un sistema Sensor → Controller → Actuator con estados claros, pruebas reproducibles y un comportamiento seguro ante fallos.',array['Python/MicroPython or Arduino','state machines','sensors','actuators','simulation']::text[],'teacher','Interés indicado por el docente: proyecto relacionado con robótica','Primero debe existir una simulación o prueba controlada. El hardware real se usa solo con alimentación, movimiento y montaje seguros.','[{"n":1,"goal":"Define the robot mission, sensor inputs, actuator outputs and success criteria.","title":"Mission + I/O","deliverable":"Project charter + I/O table"},{"n":2,"goal":"Model Sensor, Controller, Actuator and Robot plus state transitions.","title":"Architecture + state diagram","deliverable":"UML + state diagram"},{"n":3,"goal":"Simulate deterministic inputs and expected outputs before integrating hardware.","title":"Sensor/actuator simulation","deliverable":"Runnable simulation"},{"n":4,"goal":"Implement reusable controller classes and decision logic.","title":"Controller implementation","deliverable":"Class-based control layer"},{"n":5,"goal":"Handle normal transitions, invalid readings and safe fallback.","title":"State machine + fail-safe","deliverable":"State tests + fail-safe evidence"},{"n":6,"goal":"Test multiple sensor sequences against expected actuator behavior.","title":"Scenario testing","deliverable":"Test matrix + fixes"},{"n":7,"goal":"Connect hardware if available or strengthen the simulation with realistic timing/noise.","title":"Integration","deliverable":"Integrated prototype"},{"n":8,"goal":"Run a normal and failure scenario live and explain the architecture.","title":"Robotics defense","deliverable":"Final prototype + UML + live defense"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de robótica.',null,'guided_definition','["¿Qué tarea concreta debe realizar el robot?","¿Qué sensores necesita para observar su entorno?","¿Qué actuadores producirán la acción?","¿Harás simulación, hardware o ambos?","¿Cuál será el estado seguro cuando un sensor falle?"]'::jsonb),
('93fc963c-4b9b-4403-946e-9d005d243500'::uuid,'11B','ARBELAEZ ESCOBAR PEDRO PABLO','arbelaez-defensive-cyber-definition','cybersecurity','Defensive Cybersecurity Project — Define the Asset & Defense','Ruta personalizada de ciberseguridad defensiva. El proyecto concreto se define hoy: primero se elige un activo de laboratorio, un riesgo autorizado y una defensa medible.','Construir y evaluar una defensa en un entorno propio o sandbox, con énfasis en validación, control de acceso, monitoreo, hardening o simulación segura.',array['Python or Web','input validation','logging','access control','threat modeling','safe sandbox']::text[],'github_issue','Issue #12: interés en ciberseguridad defensiva / hacking ético, robótica o 3D. Ruta actual: ciberseguridad defensiva hasta definir foco.','Solo sistemas propios o sandbox expresamente autorizado. No se prueban credenciales, vulnerabilidades o indisponibilidad sobre servicios de terceros.','[{"n":1,"goal":"Define the authorized asset, threat scenario, boundaries and measurable objective.","title":"Asset + threat definition","deliverable":"Scope + threat model"},{"n":2,"goal":"Model components, roles, data flow and trust boundaries.","title":"Architecture + trust boundaries","deliverable":"UML/architecture diagram"},{"n":3,"goal":"Build or configure the local sandbox and record baseline behavior.","title":"Safe baseline lab","deliverable":"Working baseline + evidence"},{"n":4,"goal":"Implement the selected defense: validation, RBAC, rate limit, hardening or another approved control.","title":"Defensive control","deliverable":"Defense implementation"},{"n":5,"goal":"Record relevant security events and make them understandable.","title":"Logging + monitoring","deliverable":"Audit log / monitoring view"},{"n":6,"goal":"Execute bounded test cases that verify allowed and denied behavior.","title":"Authorized tests","deliverable":"Security test matrix"},{"n":7,"goal":"Fix weaknesses, reduce ambiguity and document residual limitations.","title":"Hardening + documentation","deliverable":"Hardening commit + report"},{"n":8,"goal":"Demonstrate the defense live and explain scope, evidence and limitations.","title":"Security defense","deliverable":"Final demo + security report"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de ciberseguridad defensiva.',null,'guided_definition','["¿Qué activo de laboratorio quieres proteger?","¿Qué riesgo defensivo quieres estudiar: autenticación, validación, logs, permisos, disponibilidad u otro?","¿Cómo medirás si la defensa funciona?","¿Qué pruebas autorizadas demostrarán el antes y el después?"]'::jsonb),
('6b66565a-5a36-43b4-ba2e-93d34c007ec1'::uuid,'11B','CHAVARRIAGA AVENDAÑO SAMUEL','chavarriaga-3d-print-definition','3d-programming','3D Printing Project — Define a Functional Object','Ruta personalizada de diseño e impresión 3D. El objeto final no se impone: hoy se define una pieza funcional, sus dimensiones, restricciones y variables paramétricas.','Diseñar una pieza reproducible, validar dimensiones y tolerancias, exportarla correctamente y documentar al menos una iteración de mejora.',array['OpenSCAD or FreeCAD','parametric CAD','STL','slicer','3D printing']::text[],'teacher','Interés expresado por el estudiante: impresión 3D','La impresión física depende de disponibilidad del equipo. Deben respetarse límites de tamaño, temperatura, movimiento y manipulación segura de la impresora.','[{"n":1,"goal":"Define the functional object, user, dimensions, constraints and MVP.","title":"Object + constraints","deliverable":"Dimension sheet + sketch"},{"n":2,"goal":"Identify adjustable parameters, coordinate convention and part structure.","title":"Parametric plan","deliverable":"Parameter table + model plan/UML"},{"n":3,"goal":"Create the first valid parametric geometry.","title":"Base geometry","deliverable":"First generated 3D model"},{"n":4,"goal":"Add reusable walls, holes, fillets/chamfers, patterns or modules as required.","title":"Reusable features","deliverable":"Feature-complete model draft"},{"n":5,"goal":"Validate dimensions, wall thickness, fits and constraints.","title":"Assembly + tolerances","deliverable":"Constraint check + assembled model"},{"n":6,"goal":"Export and inspect orientation, scale, supports and printability.","title":"STL + slicer","deliverable":"STL + slicer evidence"},{"n":7,"goal":"Print if available or use slicer evidence; document one problem and improvement.","title":"Prototype iteration","deliverable":"Iteration log + revised model"},{"n":8,"goal":"Change one parameter live, regenerate the model and explain design decisions.","title":"3D defense","deliverable":"Final STL/model + live parameter demo"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de impresión 3D.',null,'guided_definition','["¿Qué objeto útil quieres diseñar?","¿Quién lo usará y qué problema resuelve?","¿Cuáles son sus dimensiones límite?","¿Qué parámetros deberían poder cambiarse?","¿Necesita ensamblaje, tolerancias, agujeros o piezas móviles?"]'::jsonb),
('ac71fbd2-42f3-464e-b877-01d285f67b0d'::uuid,'11B','JARAMILLO PALACIO PABLO','jaramillo-web-definition','web','Web Application Project — Define the User, Problem & MVP','Ruta personalizada de desarrollo web. El tema no está impuesto: hoy debes definir para quién será la página o aplicación, qué problema resolverá y cuáles serán sus funciones mínimas.','Diseñar, implementar, probar y publicar una aplicación web coherente, usando un modelo de datos claro y al menos una interacción real que vaya más allá de una página estática.',array['HTML','CSS','JavaScript','JSON or API','localStorage or backend if justified','Git']::text[],'github_issue','Issue #14: desarrollo web',null,'[{"n":1,"goal":"Define the user, problem, three essential features and success criteria.","title":"User + problem + MVP","deliverable":"Project charter + prioritized backlog"},{"n":2,"goal":"Design navigation, main screens and the entities/data the app needs.","title":"Information architecture + data model","deliverable":"Wireframe + UML/data model"},{"n":3,"goal":"Build the semantic HTML/CSS shell and responsive navigation.","title":"Responsive interface","deliverable":"Navigable responsive UI"},{"n":4,"goal":"Implement the most important user action in JavaScript.","title":"Core interaction","deliverable":"Working core feature"},{"n":5,"goal":"Connect JSON/API/localStorage or a justified backend and validate inputs.","title":"Data + persistence","deliverable":"Working data flow + invalid-case handling"},{"n":6,"goal":"Add a project-specific feature such as search, filters, dashboard, forms, calendar or another justified interaction.","title":"Domain feature","deliverable":"Second functional feature"},{"n":7,"goal":"Test mobile layout, keyboard use, empty states, reload and edge cases; refactor.","title":"QA + accessibility","deliverable":"QA checklist + fixes"},{"n":8,"goal":"Publish the application and defend the user problem, architecture and testing.","title":"Deploy + defense","deliverable":"Deployment URL + final UML + live demo"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de desarrollo web. El tema final puede ser completamente diferente al de otros estudiantes del mismo track.',null,'guided_definition','["¿Quién va a usar tu aplicación?","¿Qué problema concreto resolverá?","¿Cuáles son las 3 funciones indispensables del MVP?","¿Qué datos necesita guardar o mostrar?","¿Qué hará el usuario que demuestre interacción real?","¿Cómo sabrás que el proyecto funciona correctamente?"]'::jsonb),
('be504b5a-5f22-4317-8696-fdc620b0a7f0'::uuid,'11B','RICO PARAMO ALEJANDRO','rico-portable-python-visual-show','data-science','Portable Python Visual Show — USB Launcher & Procedural Animation','Proyecto específico de Alejandro Rico: crear una experiencia visual procedural en Python preparada para ejecutarse offline desde una memoria USB mediante un lanzador visible y controlado.','Diseñar una animación visual compleja, estructurarla con clases reutilizables y empaquetarla para ejecución portátil con rutas relativas y pruebas reales offline.',array['Python','Pygame or Manim','procedural animation','PyInstaller','portable folder','visible launcher']::text[],'teacher','Definido por el docente: animación visual Python para ejecución portátil desde memoria flash','La ejecución desde USB debe iniciarse de forma visible por el usuario mediante un launcher. No se implementa autorun oculto, persistencia del sistema, evasión de controles ni comportamiento similar a malware.','[{"n":1,"goal":"Define the visual experience, duration/interaction and portable MVP.","title":"Visual concept + storyboard","deliverable":"Storyboard + acceptance criteria"},{"n":2,"goal":"Model Scene, VisualElement, Effect, Timeline/Controller and Launcher responsibilities.","title":"Animation architecture","deliverable":"UML + scene graph"},{"n":3,"goal":"Render a fluid first scene with deterministic timing.","title":"First animation loop","deliverable":"Runnable scene + sample evidence"},{"n":4,"goal":"Implement reusable motion/effect classes and parameter controls.","title":"Reusable effects","deliverable":"At least three reusable effects"},{"n":5,"goal":"Load local assets and settings with relative paths so the project is portable.","title":"Assets + relative paths","deliverable":"Offline asset/config flow"},{"n":6,"goal":"Create a packaged build or controlled Python environment plus a visible manual launcher.","title":"Portable build + launcher","deliverable":"Portable folder + launcher instructions"},{"n":7,"goal":"Test from removable media or a clean folder with no network and fix dependency/path failures.","title":"USB/offline QA","deliverable":"Compatibility checklist + fixes"},{"n":8,"goal":"Launch manually from portable media, change one visual parameter live and explain architecture.","title":"Live visual defense","deliverable":"Final portable demo + UML + README"}]'::jsonb,'assigned',null,'proposed','Proyecto específico definido. Hoy se concreta el storyboard, librería, formato de empaquetado y criterio de portabilidad.',null,'fixed','["¿La experiencia será interactiva o una animación lineal?","¿Cuál será el estilo visual y duración?","¿Usarás Pygame o Manim y por qué?","¿Qué parámetros visuales podrán cambiarse?","¿Cómo demostrarás que funciona offline desde otra ruta/unidad?"]'::jsonb),
('3d5d23cb-648c-4bed-9aa4-043686cd091d'::uuid,'11C','CORTES PAJON SAMUEL','cortes-web-definition','web','Web Application Project — Define the User, Problem & MVP','Ruta personalizada de desarrollo web. El tema no está impuesto: hoy debes definir para quién será la página o aplicación, qué problema resolverá y cuáles serán sus funciones mínimas.','Diseñar, implementar, probar y publicar una aplicación web coherente, usando un modelo de datos claro y al menos una interacción real que vaya más allá de una página estática.',array['HTML','CSS','JavaScript','JSON or API','localStorage or backend if justified','Git']::text[],'github_issue','Issue #15: interés en desarrollo web. El foco GTA/bypass NO se asume; el tema se redefine hoy con alcance seguro.','Si el estudiante elige una temática de videojuegos, el proyecto debe ser informativo o de gestión. No se implementan bypass, cheats, evasión de anti-cheat/DRM ni acceso no autorizado.','[{"n":1,"goal":"Define the user, problem, three essential features and success criteria.","title":"User + problem + MVP","deliverable":"Project charter + prioritized backlog"},{"n":2,"goal":"Design navigation, main screens and the entities/data the app needs.","title":"Information architecture + data model","deliverable":"Wireframe + UML/data model"},{"n":3,"goal":"Build the semantic HTML/CSS shell and responsive navigation.","title":"Responsive interface","deliverable":"Navigable responsive UI"},{"n":4,"goal":"Implement the most important user action in JavaScript.","title":"Core interaction","deliverable":"Working core feature"},{"n":5,"goal":"Connect JSON/API/localStorage or a justified backend and validate inputs.","title":"Data + persistence","deliverable":"Working data flow + invalid-case handling"},{"n":6,"goal":"Add a project-specific feature such as search, filters, dashboard, forms, calendar or another justified interaction.","title":"Domain feature","deliverable":"Second functional feature"},{"n":7,"goal":"Test mobile layout, keyboard use, empty states, reload and edge cases; refactor.","title":"QA + accessibility","deliverable":"QA checklist + fixes"},{"n":8,"goal":"Publish the application and defend the user problem, architecture and testing.","title":"Deploy + defense","deliverable":"Deployment URL + final UML + live demo"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de desarrollo web. El tema final puede ser completamente diferente al de otros estudiantes del mismo track.',null,'guided_definition','["¿Quién va a usar tu aplicación?","¿Qué problema concreto resolverá?","¿Cuáles son las 3 funciones indispensables del MVP?","¿Qué datos necesita guardar o mostrar?","¿Qué hará el usuario que demuestre interacción real?","¿Cómo sabrás que el proyecto funciona correctamente?"]'::jsonb),
('6f9926c7-ab3e-429a-8573-094c4a6512f6'::uuid,'11C','GONZALEZ GIRALDO TOMAS','gonzalez-data-analyst-definition','data-science','Python / Data Analyst Project — Define Your Question & Dataset','Ruta personalizada de análisis de datos en Python. El tema concreto no está impuesto: hoy debes escoger una pregunta real, un dataset y el producto final que vas a construir. La IA puede quedar como extensión si tiene sentido después del análisis exploratorio.','Convertir una pregunta elegida por el estudiante en un análisis reproducible: cargar datos, limpiar, explorar, visualizar, interpretar y comunicar hallazgos con Python.',array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[],'github_issue','Interés previo: Inteligencia Artificial Introductoria (Issue #13). Ruta actual abierta a Data Analyst / Python hasta definir el proyecto específico.',null,'[{"n":1,"goal":"Choose a real analytical question, dataset source, variables and success criteria.","title":"Question + dataset definition","deliverable":"Project charter + dataset link/source"},{"n":2,"goal":"Load the dataset reproducibly and understand columns, units, types and scope.","title":"Import + data dictionary","deliverable":"Notebook + data dictionary"},{"n":3,"goal":"Handle types, missing values, duplicates and obvious inconsistencies with documented decisions.","title":"Data cleaning","deliverable":"Clean dataset pipeline + before/after evidence"},{"n":4,"goal":"Compute relevant descriptive statistics and explore distributions/relationships.","title":"Descriptive analysis","deliverable":"EDA notebook section + findings"},{"n":5,"goal":"Build clear plots that directly answer parts of the analytical question.","title":"Visualization","deliverable":"At least 3 justified visualizations"},{"n":6,"goal":"Add grouping, correlation, hypothesis-style comparisons or a simple ML model only if justified.","title":"Deeper analysis / optional model","deliverable":"Analysis extension + interpretation"},{"n":7,"goal":"Organize the notebook/report, rerun from a clean state and verify every result.","title":"Data story + reproducibility QA","deliverable":"Reproducible final notebook/dashboard draft"},{"n":8,"goal":"Present the question, evidence, findings, limitations and one live code/data operation.","title":"Analyst defense","deliverable":"Final notebook/dashboard + short presentation"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy. La ruta base es Data Analyst / Python; el tema, dataset y producto final los define cada estudiante.',null,'guided_definition','["¿Qué pregunta real quieres responder con datos?","¿Qué dataset usarás y cuál es su fuente?","¿Qué variable o resultado te interesa explicar?","¿Qué 3 visualizaciones serían útiles?","¿Tu producto final será notebook, dashboard, informe o una combinación?","¿La IA/ML aporta valor real o basta con análisis estadístico y visual?"]'::jsonb),
('58ab3ae2-a579-4ba6-bde8-73c4f799373f'::uuid,'11C','RINCON TORRES ALEJANDRO','rincon-data-analyst-definition','data-science','Python / Data Analyst Project — Define Your Question & Dataset','Ruta personalizada de análisis de datos en Python. El tema concreto no está impuesto: hoy debes escoger una pregunta real, un dataset y el producto final que vas a construir. La IA puede quedar como extensión si tiene sentido después del análisis exploratorio.','Convertir una pregunta elegida por el estudiante en un análisis reproducible: cargar datos, limpiar, explorar, visualizar, interpretar y comunicar hallazgos con Python.',array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[],'github_issue','Interés previo: Inteligencia Artificial Introductoria (Issue #13). Ruta actual abierta a Data Analyst / Python hasta definir el proyecto específico.',null,'[{"n":1,"goal":"Choose a real analytical question, dataset source, variables and success criteria.","title":"Question + dataset definition","deliverable":"Project charter + dataset link/source"},{"n":2,"goal":"Load the dataset reproducibly and understand columns, units, types and scope.","title":"Import + data dictionary","deliverable":"Notebook + data dictionary"},{"n":3,"goal":"Handle types, missing values, duplicates and obvious inconsistencies with documented decisions.","title":"Data cleaning","deliverable":"Clean dataset pipeline + before/after evidence"},{"n":4,"goal":"Compute relevant descriptive statistics and explore distributions/relationships.","title":"Descriptive analysis","deliverable":"EDA notebook section + findings"},{"n":5,"goal":"Build clear plots that directly answer parts of the analytical question.","title":"Visualization","deliverable":"At least 3 justified visualizations"},{"n":6,"goal":"Add grouping, correlation, hypothesis-style comparisons or a simple ML model only if justified.","title":"Deeper analysis / optional model","deliverable":"Analysis extension + interpretation"},{"n":7,"goal":"Organize the notebook/report, rerun from a clean state and verify every result.","title":"Data story + reproducibility QA","deliverable":"Reproducible final notebook/dashboard draft"},{"n":8,"goal":"Present the question, evidence, findings, limitations and one live code/data operation.","title":"Analyst defense","deliverable":"Final notebook/dashboard + short presentation"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy. La ruta base es Data Analyst / Python; el tema, dataset y producto final los define cada estudiante.',null,'guided_definition','["¿Qué pregunta real quieres responder con datos?","¿Qué dataset usarás y cuál es su fuente?","¿Qué variable o resultado te interesa explicar?","¿Qué 3 visualizaciones serían útiles?","¿Tu producto final será notebook, dashboard, informe o una combinación?","¿La IA/ML aporta valor real o basta con análisis estadístico y visual?"]'::jsonb),
('995d1e6e-888e-4cee-a9f3-8b792d607233'::uuid,'11C','VELASQUEZ BELTRAN SAMUEL','velasquez-web-definition','web','Web Application Project — Define the User, Problem & MVP','Ruta personalizada de desarrollo web. El tema no está impuesto: hoy debes definir para quién será la página o aplicación, qué problema resolverá y cuáles serán sus funciones mínimas.','Diseñar, implementar, probar y publicar una aplicación web coherente, usando un modelo de datos claro y al menos una interacción real que vaya más allá de una página estática.',array['HTML','CSS','JavaScript','JSON or API','localStorage or backend if justified','Git']::text[],'github_issue','Issue #14: desarrollo web',null,'[{"n":1,"goal":"Define the user, problem, three essential features and success criteria.","title":"User + problem + MVP","deliverable":"Project charter + prioritized backlog"},{"n":2,"goal":"Design navigation, main screens and the entities/data the app needs.","title":"Information architecture + data model","deliverable":"Wireframe + UML/data model"},{"n":3,"goal":"Build the semantic HTML/CSS shell and responsive navigation.","title":"Responsive interface","deliverable":"Navigable responsive UI"},{"n":4,"goal":"Implement the most important user action in JavaScript.","title":"Core interaction","deliverable":"Working core feature"},{"n":5,"goal":"Connect JSON/API/localStorage or a justified backend and validate inputs.","title":"Data + persistence","deliverable":"Working data flow + invalid-case handling"},{"n":6,"goal":"Add a project-specific feature such as search, filters, dashboard, forms, calendar or another justified interaction.","title":"Domain feature","deliverable":"Second functional feature"},{"n":7,"goal":"Test mobile layout, keyboard use, empty states, reload and edge cases; refactor.","title":"QA + accessibility","deliverable":"QA checklist + fixes"},{"n":8,"goal":"Publish the application and defend the user problem, architecture and testing.","title":"Deploy + defense","deliverable":"Deployment URL + final UML + live demo"}]'::jsonb,'assigned',null,'proposed','Proyecto específico por definir hoy dentro de desarrollo web. El tema final puede ser completamente diferente al de otros estudiantes del mismo track.',null,'guided_definition','["¿Quién va a usar tu aplicación?","¿Qué problema concreto resolverá?","¿Cuáles son las 3 funciones indispensables del MVP?","¿Qué datos necesita guardar o mostrar?","¿Qué hará el usuario que demuestre interacción real?","¿Cómo sabrás que el proyecto funciona correctamente?"]'::jsonb)
on conflict (student_registry_id) do update set
  group_code=excluded.group_code,
  student_name=excluded.student_name,
  project_slug=excluded.project_slug,
  track_slug=excluded.track_slug,
  project_title=excluded.project_title,
  project_summary=excluded.project_summary,
  objective=excluded.objective,
  stack=excluded.stack,
  source_kind=excluded.source_kind,
  source_ref=excluded.source_ref,
  safety_scope=excluded.safety_scope,
  sprints=excluded.sprints,
  assignment_status=excluded.assignment_status,
  teacher_note=excluded.teacher_note,
  decision_status=excluded.decision_status,
  decision_note=excluded.decision_note,
  confirmed_at=excluded.confirmed_at,
  project_mode=excluded.project_mode,
  definition_questions=excluded.definition_questions,
  updated_at=clock_timestamp();
